def get_alarms_from_all_pages(instance, alarm_type, timeout, **kwargs):
    """Fetches all alarms (active or historical) from all pages."""

    fetch_function = _get_fetch_function_by_alarm_type(instance=instance, alarm_type=alarm_type)

    response = fetch_function(page_number=1, items_per_page=100, timeout=timeout, **kwargs)
    alarms = response["alarms"]
    total = response["total"]

    page_number = 2
    while len(alarms) != total:
        response = fetch_function(
            page_number=page_number, items_per_page=100, timeout=timeout, **kwargs
        )
        alarms.extend(response["alarms"])
        page_number += 1

    return {"alarms": alarms, "total": total}


def _get_fetch_function_by_alarm_type(instance, alarm_type):
    if alarm_type == "active":
        return instance.get_active_alarms
    elif alarm_type == "historical":
        return instance.get_historical_alarms
    else:
        raise ValueError("Invalid alarm_type. Choose 'active' or 'historical'.")
